# edit_engineimport streamlit as stimport sysfrom pathlib import Path# 1. ACCURATELY ANCHOR THE APP ROOT (NoLI_App)app_root = Path(__file__).resolve().parent.parentif str(app_root) not in sys.path:    sys.path.insert(0, str(app_root))# 2. LOCAL ENGINE RE-ANCHORING FOR TOOLS LOOKUPengines_dir = Path(__file__).resolve().parentif str(engines_dir) not in sys.path:    sys.path.insert(0, str(engines_dir))    # Import core utility toolsfrom edit_tools.dropdown_factory import build_edit_dropdown_optionsfrom edit_tools.editor_mechanics import load_logic_contentfrom utils.config_logic import TYPE_LABELS# Import our UI sub-modulesfrom edit_tools.view_library import render_suggestion_libraryfrom edit_tools.active_workspace import render_active_workspacefrom edit_tools.staged_review import render_staged_review# Import the clean prompt modular toolsfrom edit_tools.prompt_library import render_prompt_suggestion_librarydef run_edit_workflow(PATHS, get_all_spec_files, extract_itw_display_name):    st.title("Logic Map Files")    st.header("Edit Logic Maps")        spec_files = get_all_spec_files()    if not spec_files:        st.warning("No logic maps found in the /spec directory.")        return    # --- 1. THE TRIGGER (The If) ---    file_map, display_options = build_edit_dropdown_options(        PATHS, spec_files, extract_itw_display_name    )    selected_label = st.selectbox("Select File", options=[""] + display_options)    # --- 2. THE DATA ACTION (The Then) ---    if selected_label:        target_path = file_map[selected_label]        itw_id = extract_itw_display_name(target_path.name)                prefix = target_path.name.split('_')[0] if '_' in target_path.name else ""                state_additions_key = f"staged_additions_{prefix}_{itw_id}"        if state_additions_key not in st.session_state:            st.session_state[state_additions_key] = {}                    type_info = TYPE_LABELS.get(prefix, (prefix, "Logic Map File"))        friendly_name, protocol_desc = type_info                st.subheader(f"{friendly_name}")        st.info(f"**Protocol Intent:** {protocol_desc}")                # Load physical configurations        disk_content, sorted_keys = load_logic_content(target_path)                # MODULE 1: Render Standard Suggestion Expander Vault        render_suggestion_library(prefix, itw_id, state_additions_key, disk_content)                # MODULE 1.5: Render the Prompt Suggestion Vault        render_prompt_suggestion_library(prefix, itw_id, disk_content)                                        # MODULE 2: Active Registry Workspace (On-Disk Canvas)        updated_content = {}        render_active_workspace(PATHS, itw_id, sorted_keys, disk_content, selected_label, updated_content)        # MODULE 3: Staged Selections Editor and Saving Mechanism        render_staged_review(state_additions_key, selected_label, updated_content, target_path)